{
  "items": [
    {
      "name": "Finset.card_eq_sum_card_fiberwise",
      "module_name": "Mathlib.Algebra.BigOperators.Group.Finset.Basic",
      "kind": "theorem",
      "type": "∀ {ι : Type u_1} {M : Type u_4} [inst : DecidableEq M] {f : ι → M} {s : Finset ι} {t : Finset M},\n  Set.MapsTo f ↑s ↑t → s.card = ∑ b ∈ t, {a ∈ s | f a = b}.card"
    },
    {
      "name": "Finset.sum_card_fiberwise_eq_card_filter",
      "module_name": "Mathlib.Algebra.BigOperators.Group.Finset.Basic",
      "kind": "theorem",
      "type": "∀ {ι : Type u_1} {κ : Type u_5} [inst : DecidableEq κ] (s : Finset ι) (t : Finset κ) (g : ι → κ),\n  ∑ j ∈ t, {i ∈ s | g i = j}.card = {i ∈ s | g i ∈ t}.card"
    },
    {
      "name": "Finset.card_eq_sum_card_image",
      "module_name": "Mathlib.Algebra.BigOperators.Group.Finset.Basic",
      "kind": "theorem",
      "type": "∀ {ι : Type u_1} {M : Type u_4} [inst : DecidableEq M] (f : ι → M) (s : Finset ι),\n  s.card = ∑ b ∈ Finset.image f s, {a ∈ s | f a = b}.card"
    },
    {
      "name": "Finset.card_preimage_eq_sum_card_image_eq",
      "module_name": "Mathlib.Algebra.BigOperators.Ring.Nat",
      "kind": "theorem",
      "type": "∀ {ι : Type u_1} {M : Type u_2} {f : ι → M} {s : Finset M},\n  (∀ b ∈ s, {a | f a = b}.Finite) → Nat.card ↑(f ⁻¹' ↑s) = ∑ b ∈ s, Nat.card { a // f a = b }"
    },
    {
      "name": "Finset.card_eq_sum_ones",
      "module_name": "Mathlib.Algebra.BigOperators.Group.Finset.Basic",
      "kind": "theorem",
      "type": "∀ {ι : Type u_1} (s : Finset ι), s.card = ∑ x ∈ s, 1"
    }
  ]
}
